WITH payload AS (SELECT json_parse(http_get('https://defillama.com/api/public/near/revenue')) AS body)
SELECT section, metric, CAST(json_extract_scalar(kpi,'$.value') AS DOUBLE) AS value,
unit, json_extract_scalar(kpi,'$.formatted') AS display_value, related_chart_latest_date,
current_timestamp AS retrieved_utc
FROM payload CROSS JOIN UNNEST(
 ARRAY['Fees','Fees','Fees','Fees','Fees','Fees','Revenue','Revenue','Revenue','Revenue','Revenue','Emissions','Emissions','Emissions','Emissions','Emissions'],
 ARRAY['allTimeFees','ytdFees','thirtyDayFees','allTimeIntent','allTimeProtocol','latestCumulative','allTimeRevenue','ytdRevenue','thirtyDayRevenue','twelveMonthRevenue','latestCumulative','latestRevenue','latestEmissions','latestPercentage','netPosition','circulatingSupply'],
 ARRAY['NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','NEAR','%','NEAR','NEAR'],
 ARRAY[json_extract(body,'$.fees.kpis.allTimeFees'),json_extract(body,'$.fees.kpis.ytdFees'),json_extract(body,'$.fees.kpis.thirtyDayFees'),json_extract(body,'$.fees.kpis.allTimeIntent'),json_extract(body,'$.fees.kpis.allTimeProtocol'),json_extract(body,'$.fees.kpis.latestCumulative'),json_extract(body,'$.revenue.kpis.allTimeRevenue'),json_extract(body,'$.revenue.kpis.ytdRevenue'),json_extract(body,'$.revenue.kpis.thirtyDayRevenue'),json_extract(body,'$.revenue.kpis.twelveMonthRevenue'),json_extract(body,'$.revenue.kpis.latestCumulative'),json_extract(body,'$.emissions.kpis.latestRevenue'),json_extract(body,'$.emissions.kpis.latestEmissions'),json_extract(body,'$.emissions.kpis.latestPercentage'),json_extract(body,'$.emissions.kpis.netPosition'),json_extract(body,'$.emissions.kpis.circulatingSupply')],
 ARRAY[CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.fees.feesChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.revenue.revenueChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.revenue.revenueChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.revenue.revenueChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.revenue.revenueChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.revenue.revenueChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.emissions.revenueVsEmissionsChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.emissions.revenueVsEmissionsChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.emissions.revenueVsEmissionsChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.emissions.revenueVsEmissionsChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE),CAST(element_at(CAST(json_extract(body,'$.emissions.revenueVsEmissionsChart.dates') AS ARRAY(VARCHAR)), -1) AS DATE)]
) AS t(section,metric,unit,kpi,related_chart_latest_date)
ORDER BY section,metric
